@Override
public int read(byte[] b, int off, int len) throws IOException {
    if (position >= totalSize) {
        return -1;
    }
    int n = StreamCache.this.readAt(position, b, off, len);
    if (n > 0) {
        position += n;
    }
    return n;
}
